    int num = 50;
    // declare a pointer to num

    // double the value using the pointer

    // print the updated value of num
    return 0;
}

questions.solution:
#include <stdio.h>

int main() {
    int num = 50;
    int *ptr = &num;       /* pointer to num */

    *ptr = *ptr * 2;       /* double the value via pointer */

    printf("Updated value: %d\n", num);  /* prints 100 */
    return 0;
}
